package com.opencrm.order.execution;
import com.opencrm.common.order.AcceptedOrderSnapshot;
import com.opencrm.common.order.AcceptedOrderSnapshot.Line;
import com.opencrm.order.dto.OrderDtos.*;
import com.opencrm.order.domain.OrderProblem;
import com.opencrm.order.security.OrderAccess;
import com.opencrm.order.service.OrderService;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.flywaydb.core.Flyway;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import tools.jackson.databind.json.JsonMapper;
import java.time.*;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
@Testcontainers
@org.junit.jupiter.api.Tag("integration")
class ExecutionIntegrationTest {
 @Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine").withDatabaseName("oms");
 JdbcTemplate db;DataSourceTransactionManager manager;OrderAccess access;OrderService orders;ExecutionService execution;JsonMapper json=JsonMapper.builder().build();
 @BeforeAll static void migrate() {Flyway.configure().dataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword()).schemas("order_management").defaultSchema("order_management").load().migrate();}
 @BeforeEach void setup() {
  var ds=new DriverManagerDataSource(postgres.getJdbcUrl()+"&currentSchema=order_management",postgres.getUsername(),postgres.getPassword());db=new JdbcTemplate(ds);
  db.execute("TRUNCATE snapshot_inbox,outbox_events,execution_inbox CASCADE");manager=new DataSourceTransactionManager(ds);access=mock(OrderAccess.class);when(access.actor()).thenReturn("operator");when(access.scopeId()).thenReturn("pilot");when(access.customerIds()).thenReturn(Set.of("customer"));orders=new OrderService(db,manager,json,access,true,"pilot");execution=new ExecutionService(db,manager,json,access,true,"pilot");
 }
 View submitted(boolean recurring) {
  var line=new Line("line","product","Widget","PHYSICAL",recurring?"RECURRING":"ONE_TIME",10,"EA","10","0","0","100",recurring?"MONTHLY":"ONE_TIME",recurring?LocalDate.of(2026,1,1):null,recurring?LocalDate.of(2027,1,1):null);
  var s=new AcceptedOrderSnapshot(1,"snapshot","00000000-0000-0000-0000-000000000001","Q-1",1,"pilot","customer",Instant.parse("2026-09-01T00:00:00Z"),"USD","100","0","0","100","address","approval","tax","config",List.of(line));String payload=json.writeValueAsString(s);orders.acceptTrustedSnapshot(payload,OrderService.hash(payload));var view=orders.fromQuote(new FromQuote("snapshot",s.quoteId(),1),"convert");return orders.submit(view.id(),new Command(0,"go","submit"));
 }
 String task(String orderId,String kind) {return db.queryForObject("SELECT id FROM order_tasks WHERE order_id=? AND kind=?",String.class,orderId,kind);}
 String taskStatus(String taskId) {return db.queryForObject("SELECT status FROM order_tasks WHERE id=?",String.class,taskId);}
 @Test void manualDispatchIsDurableWaitingEvidenceNeverSyntheticSuccess() {var order=submitted(false);String task=task(order.id(),"ALLOCATION");var lease=execution.claim(task,"worker",Duration.ofSeconds(30)).orElseThrow();execution.dispatch(lease);assertEquals("WAITING_EXTERNAL",taskStatus(task));assertEquals("IN_PROGRESS",orders.get(order.id()).status());assertEquals("PENDING",orders.get(order.id()).financeStatus());assertNotNull(db.queryForObject("SELECT dispatched_at FROM order_tasks WHERE id=?",java.sql.Timestamp.class,task));assertEquals(1,db.queryForObject("SELECT count(*) FROM task_operations",Integer.class));}
 @Test void heldOrdersAndBlockedDependenciesCannotClaim() {var order=submitted(false);assertTrue(execution.claim(task(order.id(),"SHIPMENT"),"worker",Duration.ofSeconds(30)).isEmpty());orders.hold(order.id(),new Hold(1,"wait","hold",true));assertTrue(execution.claim(task(order.id(),"ALLOCATION"),"worker",Duration.ofSeconds(30)).isEmpty());}

 @Test void expiredClaimIsReclaimedAndOldWorkerCannotCommit() {var o=submitted(false);String t=task(o.id(),"ALLOCATION");var first=execution.claim(t,"worker1",Duration.ofSeconds(30)).orElseThrow();db.update("UPDATE task_operations SET lease_until=CURRENT_TIMESTAMP-interval '1 second',next_attempt_at=CURRENT_TIMESTAMP-interval '1 second' WHERE task_id=?",t);var second=execution.claim(t,"worker2",Duration.ofSeconds(30)).orElseThrow();assertEquals(first.operationKey(),second.operationKey());assertNotEquals(first.token(),second.token());assertEquals(409,assertThrows(OrderProblem.class,()->execution.dispatch(first)).status());execution.dispatch(second);assertEquals(2,db.queryForObject("SELECT attempt FROM task_operations WHERE task_id=?",Integer.class,t));}
 @Test void holdBetweenClaimAndDispatchFencesExternalIntent() {var o=submitted(false);var lease=execution.claim(task(o.id(),"ALLOCATION"),"worker",Duration.ofSeconds(30)).orElseThrow();orders.hold(o.id(),new Hold(o.version(),"stop","hold",true));assertEquals(409,assertThrows(OrderProblem.class,()->execution.dispatch(lease)).status());assertNull(db.queryForObject("SELECT dispatched_at FROM order_tasks WHERE id=?",java.sql.Timestamp.class,lease.taskId()));}
 @Test void unknownOutcomeNeverBlindlyRetries() {var o=submitted(false);var lease=execution.claim(task(o.id(),"ALLOCATION"),"worker",Duration.ofSeconds(30)).orElseThrow();execution.dispatch(lease);execution.recordUnknown(lease,"ambiguous external outcome");assertEquals("UNKNOWN",taskStatus(lease.taskId()));assertTrue(execution.claim(lease.taskId(),"worker2",Duration.ofSeconds(30)).isEmpty());long version=orders.get(o.id()).version();assertEquals(409,assertThrows(OrderProblem.class,()->execution.retry(o.id(),lease.taskId(),new Command(version,"retry","retry"))).status());assertEquals(1,db.queryForObject("SELECT count(*) FROM order_exceptions WHERE status='OPEN'",Integer.class));}
 @Test void partialEvidenceReleasesOnlyAvailableDownstreamQuantity() {var o=submitted(false);String line=o.lines().getFirst().id();db.update("UPDATE order_lines SET allocated=4 WHERE id=?",line);execution.completeManualTask(o.id(),line,"ALLOCATION","allocation-4",Instant.now());assertEquals("WAITING_EXTERNAL",taskStatus(task(o.id(),"ALLOCATION")));assertEquals("READY",taskStatus(task(o.id(),"SHIPMENT")));db.update("UPDATE order_lines SET allocated=0,shipped=4,fulfilled=4 WHERE id=?",line);execution.completeManualTask(o.id(),line,"SHIPMENT","shipment-4",Instant.now());assertEquals("WAITING_EXTERNAL",taskStatus(task(o.id(),"SHIPMENT")));assertEquals("READY",taskStatus(task(o.id(),"DELIVERY")));assertEquals("BLOCKED",taskStatus(task(o.id(),"FINANCE_ACK")));}
 void fulfill(View o) {String line=o.lines().getFirst().id();db.update("UPDATE order_lines SET allocated=10 WHERE id=?",line);execution.completeManualTask(o.id(),line,"ALLOCATION","allocation",Instant.now());db.update("UPDATE order_lines SET allocated=0,shipped=10,fulfilled=10 WHERE id=?",line);execution.completeManualTask(o.id(),line,"SHIPMENT","shipment",Instant.now());db.update("UPDATE order_lines SET delivered=10 WHERE id=?",line);execution.completeManualTask(o.id(),line,"DELIVERY","delivery",Instant.now());}
 @Test void activationDispatchIsOnceAndAcknowledgmentReplayCompletesOnlyActivation() {var o=submitted(true);fulfill(o);String task=task(o.id(),"ACTIVATION");var lease=execution.claim(task,"worker",Duration.ofSeconds(30)).orElseThrow();execution.dispatch(lease);assertEquals(409,assertThrows(OrderProblem.class,()->execution.dispatch(lease)).status());assertEquals(1,db.queryForObject("SELECT count(*) FROM outbox_events WHERE event_type='oms.activation-requested.v1'",Integer.class));assertEquals("WAITING_EXTERNAL",taskStatus(task));var ack=new com.opencrm.common.order.ActivationAcknowledgment("ack1",lease.operationKey(),o.id(),"pilot","sub1","ACKNOWLEDGED","contract-ref",Instant.now());String hash=OrderService.hash(json.writeValueAsString(ack));execution.acceptActivationAck(ack,hash);execution.acceptActivationAck(ack,hash);assertEquals("SUCCESS",taskStatus(task));assertEquals("READY",taskStatus(task(o.id(),"FINANCE_ACK")));assertEquals("IN_PROGRESS",orders.get(o.id()).status());assertEquals(1,db.queryForObject("SELECT count(*) FROM execution_inbox",Integer.class));execution.completeManualTask(o.id(),o.lines().getFirst().id(),"FINANCE_ACK","invoice-ack",Instant.now());assertEquals("COMPLETED",orders.get(o.id()).status());}
 @Test void ackWrongScopeOrAlteredBodyIsRejected() {var o=submitted(true);fulfill(o);var lease=execution.claim(task(o.id(),"ACTIVATION"),"worker",Duration.ofSeconds(30)).orElseThrow();execution.dispatch(lease);var bad=new com.opencrm.common.order.ActivationAcknowledgment("ack",lease.operationKey(),o.id(),"other","sub","ACKNOWLEDGED","ref",Instant.now());assertEquals(403,assertThrows(OrderProblem.class,()->execution.acceptActivationAck(bad,OrderService.hash("bad"))).status());var good=new com.opencrm.common.order.ActivationAcknowledgment("ack",lease.operationKey(),o.id(),"pilot","sub","ACKNOWLEDGED","ref",Instant.now());execution.acceptActivationAck(good,OrderService.hash("good"));assertEquals(409,assertThrows(OrderProblem.class,()->execution.acceptActivationAck(good,OrderService.hash("altered"))).status());}
 @Test void callbackFailureCreatesExceptionAndDoesNotReleaseFinance() {var o=submitted(true);fulfill(o);var lease=execution.claim(task(o.id(),"ACTIVATION"),"worker",Duration.ofSeconds(30)).orElseThrow();execution.dispatch(lease);var ack=new com.opencrm.common.order.ActivationAcknowledgment("ack",lease.operationKey(),o.id(),"pilot",null,"UNKNOWN","ref",Instant.now());execution.acceptActivationAck(ack,OrderService.hash(json.writeValueAsString(ack)));assertEquals("UNKNOWN",taskStatus(lease.taskId()));assertEquals("BLOCKED",taskStatus(task(o.id(),"FINANCE_ACK")));}
 @Test void deadlineRecoveryPreservesUnknownInsteadOfRedispatch() {var o=submitted(false);var lease=execution.claim(task(o.id(),"ALLOCATION"),"worker",Duration.ofSeconds(30)).orElseThrow();execution.dispatch(lease);db.update("UPDATE task_operations SET deadline_at=CURRENT_TIMESTAMP-interval '1 second' WHERE task_id=?",lease.taskId());execution.reconcileDue(10);assertEquals("UNKNOWN",taskStatus(lease.taskId()));assertTrue(execution.claim(lease.taskId(),"worker",Duration.ofSeconds(30)).isEmpty());}

 @Test void partialRecurringCancellationHoldsActivationWithoutChangedSourceTerms() {var o=submitted(true);String line=o.lines().getFirst().id();db.update("UPDATE order_lines SET cancelled=2,allocated=8 WHERE id=?",line);execution.completeManualTask(o.id(),line,"ALLOCATION","alloc8",Instant.now());db.update("UPDATE order_lines SET allocated=0,shipped=8,fulfilled=8 WHERE id=?",line);execution.completeManualTask(o.id(),line,"SHIPMENT","ship8",Instant.now());db.update("UPDATE order_lines SET delivered=8 WHERE id=?",line);execution.completeManualTask(o.id(),line,"DELIVERY","deliver8",Instant.now());var lease=execution.claim(task(o.id(),"ACTIVATION"),"worker",Duration.ofSeconds(30)).orElseThrow();execution.dispatch(lease);assertEquals("UNKNOWN",taskStatus(lease.taskId()));assertEquals(0,db.queryForObject("SELECT count(*) FROM outbox_events WHERE event_type='oms.activation-requested.v1'",Integer.class));assertEquals("PARTIAL_RECURRING_CANCELLATION",db.queryForObject("SELECT category FROM order_exceptions",String.class));}
 @Test void expiredUndispatchedAttemptsRequireExplicitVersionedRetry() {var o=submitted(false);String task=task(o.id(),"ALLOCATION");for(int i=0;i<3;i++) {assertTrue(execution.claim(task,"worker",Duration.ofSeconds(30)).isPresent());db.update("UPDATE task_operations SET lease_until=CURRENT_TIMESTAMP-interval '1 second',next_attempt_at=CURRENT_TIMESTAMP-interval '1 second' WHERE task_id=?",task);}assertTrue(execution.claim(task,"worker",Duration.ofSeconds(30)).isEmpty());assertEquals("RETRYABLE",taskStatus(task));execution.retry(o.id(),task,new Command(orders.get(o.id()).version(),"confirmed no dispatch","retry"));db.update("UPDATE task_operations SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE task_id=?",task);var lease=execution.claim(task,"worker",Duration.ofSeconds(30)).orElseThrow();assertEquals(1,lease.attempt());}
 @Test void evidenceMutationAndExecutionCompletionRollbackTogether() {var o=submitted(false);String line=o.lines().getFirst().id();assertThrows(IllegalStateException.class,()->new org.springframework.transaction.support.TransactionTemplate(manager).executeWithoutResult(t->{db.update("UPDATE order_lines SET allocated=10 WHERE id=?",line);execution.completeManualTask(o.id(),line,"ALLOCATION","proof",Instant.now());throw new IllegalStateException("writer failed before commit");}));assertEquals(0,orders.get(o.id()).lines().getFirst().allocated());assertEquals("READY",taskStatus(task(o.id(),"ALLOCATION")));assertEquals(0,db.queryForObject("SELECT count(*) FROM task_operations",Integer.class));}
 @Test void competingWorkersObtainOneActiveLease() throws Exception {var o=submitted(false);String task=task(o.id(),"ALLOCATION");try(var pool=java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()) {var gate=new java.util.concurrent.CountDownLatch(1);var results=new ArrayList<java.util.concurrent.Future<Boolean>>();for(int i=0;i<20;i++){final int n=i;results.add(pool.submit(()->{gate.await();return execution.claim(task,"worker"+n,Duration.ofSeconds(30)).isPresent();}));}gate.countDown();int winners=0;for(var f:results)if(f.get(30,java.util.concurrent.TimeUnit.SECONDS))winners++;assertEquals(1,winners);}}

 @Test void transactionStartTimeCannotExtendExpiredWorkerLease() {var o=submitted(false);var lease=execution.claim(task(o.id(),"ALLOCATION"),"worker",Duration.ofSeconds(30)).orElseThrow();assertEquals(409,assertThrows(OrderProblem.class,()->new org.springframework.transaction.support.TransactionTemplate(manager).executeWithoutResult(t->{db.update("UPDATE task_operations SET lease_until=CURRENT_TIMESTAMP+interval '1 millisecond' WHERE task_id=?",lease.taskId());db.execute("SELECT pg_sleep(0.02)");execution.dispatch(lease);})).status());}

 @Test void releasedAllocationReopensPhaseAndFencesUndispatchedShipment() {var o=submitted(false);String line=o.lines().getFirst().id();db.update("UPDATE order_lines SET allocated=10 WHERE id=?",line);execution.completeManualTask(o.id(),line,"ALLOCATION","alloc",Instant.now());var lease=execution.claim(task(o.id(),"SHIPMENT"),"worker",Duration.ofSeconds(30)).orElseThrow();db.update("UPDATE order_lines SET allocated=0 WHERE id=?",line);execution.refreshLineReadiness(o.id(),line,"release-confirmed",Instant.now());assertEquals("WAITING_EXTERNAL",taskStatus(task(o.id(),"ALLOCATION")));assertEquals("BLOCKED",taskStatus(lease.taskId()));assertEquals(409,assertThrows(OrderProblem.class,()->execution.dispatch(lease)).status());}
 @Test void authoritativeNoEffectAllowsRetryWithSameStableOperationKey() {var o=submitted(false);var first=execution.claim(task(o.id(),"ALLOCATION"),"worker",Duration.ofSeconds(30)).orElseThrow();execution.dispatch(first);execution.recordUnknown(first,"ambiguous");execution.recordNoEffect(o.id(),first.taskId(),new Command(orders.get(o.id()).version(),"checked provider","proof"),"provider-not-found",Instant.now());assertEquals("RETRYABLE",taskStatus(first.taskId()));execution.retry(o.id(),first.taskId(),new Command(orders.get(o.id()).version(),"safe retry","retry"));db.update("UPDATE task_operations SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE task_id=?",first.taskId());var next=execution.claim(first.taskId(),"worker2",Duration.ofSeconds(30)).orElseThrow();assertEquals(first.operationKey(),next.operationKey());execution.dispatch(next);}
 @Test void heldCandidateBacklogCannotStarveEligibleWork() {var o=submitted(false);String base=o.id();for(int i=0;i<30;i++){String order=String.format("00000000-0000-0000-0000-%012d",i),line=UUID.randomUUID().toString(),task=String.format("00000000-0000-0000-0001-%012d",i);db.update("INSERT INTO orders(id,order_number,scope_id,customer_id,quote_id,quote_number,accepted_revision,snapshot_id,snapshot_json,snapshot_hash,status,manual_hold,created_at,updated_at,created_by,updated_by) SELECT ?,? ,scope_id,customer_id,?,quote_number,accepted_revision,snapshot_id,snapshot_json,snapshot_hash,status,true,created_at,updated_at,created_by,updated_by FROM orders WHERE id=?",order,"HELD-"+i,UUID.randomUUID().toString(),base);db.update("INSERT INTO order_lines(id,order_id,source_line_id,description,ordered) VALUES(?,?,'line','Held',10)",line,order);db.update("INSERT INTO order_tasks(id,order_id,line_id,kind,template_version,status) VALUES(?,?,?,'ALLOCATION',1,'READY')",task,order,line);}execution.dispatchReady(25);assertEquals("WAITING_EXTERNAL",taskStatus(task(o.id(),"ALLOCATION")));}
 @Test void schedulerExhaustionAlwaysCreatesVisibleException() {var o=submitted(false);String task=task(o.id(),"ALLOCATION");execution.claim(task,"worker",Duration.ofSeconds(30)).orElseThrow();db.update("UPDATE task_operations SET attempt=3,lease_until=clock_timestamp()-interval '1 second' WHERE task_id=?",task);execution.reconcileDue(10);assertEquals("RETRYABLE",taskStatus(task));assertEquals(1,db.queryForObject("SELECT count(*) FROM order_exceptions WHERE task_id=? AND category='ATTEMPTS_EXHAUSTED' AND status='OPEN'",Integer.class,task));}
 @Test void expiredClaimWaitsForBoundedBackoff() {var o=submitted(false);String task=task(o.id(),"ALLOCATION");execution.claim(task,"worker",Duration.ofSeconds(30)).orElseThrow();db.update("UPDATE task_operations SET lease_until=clock_timestamp()-interval '1 second' WHERE task_id=?",task);assertTrue(execution.claim(task,"worker2",Duration.ofSeconds(30)).isEmpty());var delay=db.queryForObject("SELECT EXTRACT(EPOCH FROM(next_attempt_at-clock_timestamp())) FROM task_operations WHERE task_id=?",Double.class,task);assertNotNull(delay);assertTrue(delay>0 && delay<=300);}

 @Test void delayedActivationSuccessFencesNoEffectRetry() {var o=submitted(true);fulfill(o);var lease=execution.claim(task(o.id(),"ACTIVATION"),"worker",Duration.ofSeconds(30)).orElseThrow();execution.dispatch(lease);execution.recordUnknown(lease,"response lost");execution.recordNoEffect(o.id(),lease.taskId(),new Command(orders.get(o.id()).version(),"provider lookup","proof"),"lookup-not-found",Instant.now());execution.retry(o.id(),lease.taskId(),new Command(orders.get(o.id()).version(),"retry","retry"));var ack=new com.opencrm.common.order.ActivationAcknowledgment("late-ack",lease.operationKey(),o.id(),"pilot","subscription","ACKNOWLEDGED","proof",Instant.now());execution.acceptActivationAck(ack,OrderService.hash(json.writeValueAsString(ack)));assertEquals("SUCCESS",taskStatus(lease.taskId()));assertTrue(execution.claim(lease.taskId(),"worker2",Duration.ofSeconds(30)).isEmpty());assertEquals(1,db.queryForObject("SELECT count(*) FROM outbox_events WHERE event_type='oms.activation-requested.v1'",Integer.class));}
}
